import{_ as s,l as o,o as e,c as n,v as t,p as i,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"以太网速率演进","description":"","frontmatter":{"title":"以太网速率演进","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ethernet-speeds.md","filePath":"cs/ethernet-speeds.md","lastUpdated":1789023840000}'),h={name:"cs/ethernet-speeds.md"};function C(E,a,A,P,_,m){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="以太网速率演进" tabindex="-1">以太网速率演进 <a class="header-anchor" href="#以太网速率演进" aria-label="Permalink to &quot;以太网速率演进&quot;">​</a></h1><div class="epigraph"><p>从 10 Mb/s 共享到 800 Gb/s 串行，MAC 帧几乎不动，变的是 PCS、FEC 与并行通道数。</p><footer>—— 据 IEEE 802.3 各代标准；Metcalfe and Boggs, 1976 对照整理</footer></div><p><a href="/cs/optical-transceivers-wdm">上一课</a>给出模块与波长。缺口是<strong>速率档如何叠上去</strong>：10/100/1000/10G/25G/40G/100G/400G……同一<a href="/cs/frame-mac">帧与 MAC</a> 格式，PHY 换调制、块码、FEC 与 lane。本课不把自协商状态机写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每升一档就改帧格式，交换芯片与抓包工具全断代。802.3 的策略：MAC 服务不变，介质相关子层升级。百兆 4B/5B，千兆 8B/10B，10G 64B/66B，25G+ 常配 RS-FEC。40G/100G 用多 lane 绑定（如 4×25G）。标称速率是 MAC 侧净荷量级，毛速率含编码——接住前几课的开销账。</p><p>共享同轴的 10BASE5 已退出；当代默认全双工点到点。CSMA/CD 留在主干课对照，不在本档复活。</p><p><span class="marginnote">802.3 用「BASE」命名介质与编码。多 lane 对齐是 PCS 的 deskew，不是 LACP。LACP 是后课把多条已成立链路绑成一条逻辑链路。</span></p><h3 id="升速改-phy-不改帧" tabindex="-1">升速改 PHY 不改帧 <a class="header-anchor" href="#升速改-phy-不改帧" aria-label="Permalink to &quot;升速改 PHY 不改帧&quot;">​</a></h3><p>MAC 服务稳定，变的是 PCS、FEC 与 lane。多 lane deskew 不是 LACP。标称速率对照毛符号率时必须先扣块码。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列演进轴：符号率、每符号比特、lane 数、FEC。画：MAC → Reconciliation → PCS/PMA → PMD。强调 25G 单 lane 成为数据中心积木，100G 常 4×25 或 2×50。不要背年份表当课。</p>',11)),(e(),i(c,null,{default:r(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAC%5B%22%E4%B8%8D%E5%8F%98%E7%9A%84%20MAC%20%E5%B8%A7%22%5D%20--%3E%20PCS%5B%22%E6%8D%A2%E4%BB%A3%E7%9A%84%20PCS%2FFEC%22%5D%0A%20%20PCS%20--%3E%20LANE%5B%221%20%E6%88%96%20N%20%E6%9D%A1%20SerDes%22%5D%0A%20%20LANE%20--%3E%20PMD%5B%22%E9%93%9C%E6%88%96%E5%85%89%20PMD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容量课的 \\(C\\) 随工艺与调制上升；以太网把上升收成可互操作的档。交换机「40G 口」可能是 4 条 10G lane，对 IP 仍是一个接口。主干<a href="/cs/vlan">VLAN</a> 标签加在 MAC 上，与速率档正交。</p><p>FEC 使净荷时延增加几十到几百纳秒，对存储 RoCE 后课敏感，本课只点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 802.3cg 单对以太网的全部工业剖面。自协商与双工是下一课。后课默认：升速改 PHY，不改以太网帧语义。</p><p>营销「无损以太网」是 PFC 后课，不是速率档的性质。</p><p>上一课留下的缺口在本课收口；「以太网速率演进」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/autonegotiation">自协商与双工</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>帧格式稳定；PCS、FEC、lane 承载升速。</li><li>标称速率含编码约定，对照毛符号率。</li><li>多 lane 是 PHY 绑定，不是 LACP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3；Metcalfe–Boggs, 1976。</li></ul>',10))])}const S=s(h,[["render",C]]);export{u as __pageData,S as default};
